def map : {n : ℕ} → NatTreeEmbedding n → (Fin n → ℕ) → (Fin n → ℕ)
  | 0, _, t => t
  | _ + 1, f, t => Fin.cons (f.1 (t 0)) (map (f.2 (t 0)) (Fin.tail t))

